-- 06-3-apply.sql — THE ONLY FILE THAT CHANGES public TABLES (generated by split_06.py). ONE transaction.
-- Same apply logic and checks as 06-apply-rewrites.sql, reading the proposals from
-- audit_backup.rewrites_20261122_proposals. Refuses to run unless: 01-helper.sql is installed, all
-- 320 proposals are loaded (row count + content checksum), and 06-2-backup.sql has backed up every
-- affected row (backup tables present, RLS on).
--   * A field changes ONLY when its current text still equals the stored old text; otherwise it is
--     logged as 'changed-since-review' (or 'row-missing') and left alone.
--   * Second run: 0 changes ('already-applied').
--   * Final checks raise an exception (nothing committed) on any structure/identity/status problem.
-- Run with psql -v ON_ERROR_STOP=1 -f <file>, or paste the whole file into the SQL editor (one call per file).

begin;

do $$
begin
  if to_regprocedure('translation_fix.jsonb_shape(jsonb)') is null
     or to_regprocedure('translation_fix.identity_values(jsonb)') is null then
    raise exception 'Helper missing: run 01-helper.sql first';
  end if;
end $$;


do $$
declare n int; h text;
begin
  if to_regclass('audit_backup.rewrites_20261122_proposals') is null then
    raise exception 'audit_backup.rewrites_20261122_proposals missing: run 06-0-prepare.sql and all 06-1-load-*.sql first';
  end if;
  select count(*), md5(string_agg(concat_ws(chr(31), locale, slug, field, col, coalesce(array_to_string(path, chr(30)), '~'),
                               decision, old_text, new_text),
                     chr(29) order by locale collate "C", slug collate "C", field collate "C"))
    into n, h from audit_backup.rewrites_20261122_proposals;
  if n <> 320 then
    raise exception 'audit_backup.rewrites_20261122_proposals has % rows, expected 320 (a 06-1-load file missing or the table edited by hand?)', n;
  end if;
  if h is distinct from '4b98b4cfb2908f2c3d02ebbd8419fa20' then
    raise exception 'audit_backup.rewrites_20261122_proposals content checksum % differs from the reviewed proposals (4b98b4cfb2908f2c3d02ebbd8419fa20)', h;
  end if;
end $$;

do $$
declare bad int;
begin
  if to_regclass('audit_backup.rewrites_20261122_destinations') is null
     or to_regclass('audit_backup.rewrites_20261122_translations') is null then
    raise exception 'Backup tables missing: run 06-2-backup.sql first';
  end if;
  select count(*) into bad from pg_class c join pg_namespace s on s.oid = c.relnamespace
  where s.nspname = 'audit_backup'
    and c.relname in ('rewrites_20261122_proposals', 'rewrites_20261122_destinations', 'rewrites_20261122_translations')
    and not c.relrowsecurity;
  if bad > 0 then raise exception 'RLS is off on % audit_backup rewrite tables: run 06-2-backup.sql', bad; end if;
  -- Every affected row that exists now must already be in the backup.
  select count(*) into bad from public.destinations d
  where d.slug in (select slug from audit_backup.rewrites_20261122_proposals where locale = 'en')
    and not exists (select 1 from audit_backup.rewrites_20261122_destinations b where b.id = d.id);
  if bad > 0 then raise exception '% affected destinations are not in the backup: run 06-2-backup.sql', bad; end if;
  select count(*) into bad from public.content_translations t
  where t.entity_type = 'destination'
    and (t.locale, t.entity_id) in (select locale, slug from audit_backup.rewrites_20261122_proposals where locale <> 'en')
    and not exists (select 1 from audit_backup.rewrites_20261122_translations b where b.id = t.id);
  if bad > 0 then raise exception '% affected translations are not in the backup: run 06-2-backup.sql', bad; end if;
end $$;

-- ============================================================================================
-- 2. Apply. One UPDATE per proposal, guarded by "current text = reviewed old text".
-- ============================================================================================
create temp table fix_log (
  locale text, slug text, field text, decision text,
  status text,        -- applied | already-applied | changed-since-review | row-missing
  rows_changed int
) on commit drop;

do $$
declare
  p   record;
  cur text;
  hit int;
  n   int;
begin
  for p in select * from audit_backup.rewrites_20261122_proposals order by locale, slug, field loop
    n := 0;
    if p.locale = 'en' then
      select count(*),
             max(case p.col when 'tagline' then d.tagline
                            when 'seo_description' then d.seo_description
                            else d.travel_plan #>> p.path end)
        into hit, cur
        from public.destinations d where d.slug = p.slug;
    else
      select count(*), max(t.fields #>> p.path) into hit, cur
        from public.content_translations t
       where t.entity_type = 'destination' and t.entity_id = p.slug and t.locale = p.locale;
    end if;

    if hit > 1 then
      raise exception 'More than one row for % % — refusing to guess', p.locale, p.slug;
    end if;

    if hit = 0 or cur is null then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'row-missing', 0);
      continue;
    elsif cur = p.new_text then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'already-applied', 0);
      continue;
    elsif cur <> p.old_text then
      insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'changed-since-review', 0);
      continue;
    end if;

    if p.locale = 'en' and p.col = 'tagline' then
      update public.destinations set tagline = p.new_text, updated_at = now()
       where slug = p.slug and tagline = p.old_text;
    elsif p.locale = 'en' and p.col = 'seo_description' then
      update public.destinations set seo_description = p.new_text, updated_at = now()
       where slug = p.slug and seo_description = p.old_text;
    elsif p.locale = 'en' then
      update public.destinations set travel_plan = jsonb_set(travel_plan, p.path, to_jsonb(p.new_text), false),
                                     updated_at = now()
       where slug = p.slug and travel_plan #>> p.path = p.old_text;
    else
      update public.content_translations set fields = jsonb_set(fields, p.path, to_jsonb(p.new_text), false),
                                             updated_at = now()
       where entity_type = 'destination' and entity_id = p.slug and locale = p.locale
         and fields #>> p.path = p.old_text;
    end if;
    get diagnostics n = row_count;
    if n <> 1 then
      raise exception 'Expected 1 changed row for % % %, got %', p.locale, p.slug, p.field, n;
    end if;
    insert into fix_log values (p.locale, p.slug, p.field, p.decision, 'applied', n);
  end loop;
end $$;

-- ============================================================================================
-- 3. Final checks (any failure aborts the whole transaction).
-- ============================================================================================
do $$
declare bad int;
begin
  -- fix_log covers every proposal exactly once.
  select count(*) into bad from audit_backup.rewrites_20261122_proposals p
  where (select count(*) from fix_log f where f.locale = p.locale and f.slug = p.slug and f.field = p.field) <> 1;
  if bad > 0 then raise exception 'fix_log check failed: % proposals not logged exactly once', bad; end if;

  -- Every applied / already-applied field now holds exactly the reviewed new text.
  select count(*) into bad
  from fix_log f join audit_backup.rewrites_20261122_proposals p using (locale, slug, field)
  left join public.destinations d on f.locale = 'en' and d.slug = f.slug
  left join public.content_translations t on f.locale <> 'en' and t.entity_type = 'destination'
                                          and t.entity_id = f.slug and t.locale = f.locale
  where f.status in ('applied', 'already-applied')
    and (case when f.locale <> 'en' then t.fields #>> p.path
              when p.col = 'tagline' then d.tagline
              when p.col = 'seo_description' then d.seo_description
              else d.travel_plan #>> p.path end) is distinct from p.new_text;
  if bad > 0 then raise exception 'Value check failed for % fields', bad; end if;

  -- JSON structure (keys, array lengths, non-string values) identical to the backup.
  select count(*) into bad
  from public.content_translations t
  join audit_backup.rewrites_20261122_translations b on b.id = t.id
  where translation_fix.jsonb_shape(t.fields) is distinct from translation_fix.jsonb_shape(b.fields)
     or translation_fix.identity_values(t.fields) is distinct from translation_fix.identity_values(b.fields)
     or t.status is distinct from b.status;
  if bad > 0 then raise exception 'Structure/identity/status check failed for % translation rows', bad; end if;

  select count(*) into bad
  from public.destinations d
  join audit_backup.rewrites_20261122_destinations b on b.id = d.id
  where translation_fix.jsonb_shape(d.travel_plan) is distinct from translation_fix.jsonb_shape(b.travel_plan)
     or translation_fix.identity_values(d.travel_plan) is distinct from translation_fix.identity_values(b.travel_plan)
     or d.status is distinct from b.status or d.name is distinct from b.name;
  if bad > 0 then raise exception 'Structure/identity/status check failed for % destinations', bad; end if;

  -- No placeholder token in any written text.
  select count(*) into bad from audit_backup.rewrites_20261122_proposals
  where new_text ~ '\[(dated source|source datée|datierter Quelle|datiert Quelle)';
  if bad > 0 then raise exception 'Token check failed: % new texts contain a placeholder', bad; end if;
end $$;

-- Result (first run: applied; second run: already-applied; edited since review: changed-since-review).
select locale, decision, status, count(*) as fields, sum(rows_changed) as rows_changed
from fix_log group by 1, 2, 3 order by 1, 2, 3;

-- Fields skipped because their text no longer matches the review (rewrite these by hand).
select locale, slug, field, status from fix_log
where status in ('changed-since-review', 'row-missing') order by 1, 2, 3;


commit;
